(2026734, 278758, 30982, '<td valign="top">A bit grainy, and the backlighting doesn''t highlight the subject per se.</td>', 'A bit grainy, and the backlighting doesn''t highlight the subject per se.', '2006-01-11 13:55:56.000000', NULL, 1),
(2026737, 276554, 49067, '<td valign="top">silhouetted?</td>', 'silhouetted?', '2006-01-11 13:56:05.000000', NULL, 1),
