(2026747, 279479, 49067, '<td valign="top">nice idea</td>', 'nice idea', '2006-01-11 13:57:01.000000', NULL, 1),
(2026750, 279264, 30982, '<td valign="top">I''d have liked it better without the props.  Cute bunny and like the way the light "pinks" near the ear.</td>', 'I''d have liked it better without the props.  Cute bunny and like the way the light "pinks" near the ear.', '2006-01-11 13:57:45.000000', NULL, 1),
(2026751, 279572, 49067, '<td valign="top">I detect a silhouette - great shot tho</td>', 'I detect a silhouette - great shot tho', '2006-01-11 13:57:56.000000', NULL, 1),
(2026757, 279579, 30982, '<td valign="top">Pretty much meets the challenge but appears the focus is on the flat surface rather than the glass.</td>', 'Pretty much meets the challenge but appears the focus is on the flat surface rather than the glass.', '2006-01-11 13:58:52.000000', NULL, 1),
(2026765, 279596, 30982, '<td valign="top">Good approach, but lacks focus on any specific item.</td>', 'Good approach, but lacks focus on any specific item.', '2006-01-11 14:02:17.000000', NULL, 1),
(2026773, 279270, 30982, '<td valign="top">The wires near her head are distracting, but good use of backlight on her hair while keeping her face well-lit.</td>', 'The wires near her head are distracting, but good use of backlight on her hair while keeping her face well-lit.', '2006-01-11 14:03:50.000000', NULL, 1),
(2026782, 277268, 30982, '<td valign="top">It''s backlit, alright.  But not all that exciting.  (Neither is mine.)</td>', 'It''s backlit, alright.  But not all that exciting.  (Neither is mine.)', '2006-01-11 14:06:49.000000', NULL, 1),
(2026788, 279580, 30982, '<td valign="top">Popular choice for this challenge.  A bit too bright, maybe.</td>', 'Popular choice for this challenge.  A bit too bright, maybe.', '2006-01-11 14:07:20.000000', NULL, 1),
(2026789, 276551, 49067, '<td valign="top">4 22:10</td>', '4 22:10', '2006-01-11 14:08:06.000000', NULL, 1),
(2026794, 279005, 30982, '<td valign="top">Odd reflection on the wall (?) and lamp is a bit dusty, which is a bit distracting.</td>', 'Odd reflection on the wall (?) and lamp is a bit dusty, which is a bit distracting.', '2006-01-11 14:08:53.000000', NULL, 1),
(2026795, 277826, 46214, '<td valign="top">too grainy and the backlight on the mouth seems overexposed</td>', 'too grainy and the backlight on the mouth seems overexposed', '2006-01-11 14:09:04.000000', NULL, 1),
(2026799, 279375, 30982, '<td valign="top">Very nicely lit and composed, but I''d have preferred more of the flower in focus.</td>', 'Very nicely lit and composed, but I''d have preferred more of the flower in focus.', '2006-01-11 14:09:44.000000', NULL, 1),
(2026800, 278775, 46214, '<td valign="top">a little bit small and maybe is the background a bit distracting</td>', 'a little bit small and maybe is the background a bit distracting', '2006-01-11 14:09:51.000000', NULL, 1),
(2026802, 279025, 30982, '<td valign="top">More "underlit" than "backlit"</td>', 'More "underlit" than "backlit"', '2006-01-11 14:10:12.000000', NULL, 1),
(2026806, 278949, 46214, '<td valign="top">the face is a little bit to dark and the reflexes draws to much attention from the man</td>', 'the face is a little bit to dark and the reflexes draws to much attention from the man', '2006-01-11 14:11:11.000000', NULL, 1),
(2026807, 279121, 46214, '<td valign="top">out of focus</td>', 'out of focus', '2006-01-11 14:11:31.000000', NULL, 1),
(2026810, 277801, 30982, '<td valign="top">Good halo effect but a bit of "flare" on her dress.</td>', 'Good halo effect but a bit of "flare" on her dress.', '2006-01-11 14:11:53.000000', NULL, 1),
(2026812, 278949, 30982, '<td valign="top">Nice interpretation of your challenge.</td>', 'Nice interpretation of your challenge.', '2006-01-11 14:12:50.000000', NULL, 1),
(2026813, 279060, 30982, '<td valign="top">Very effective use of backlighting - good response to the challenge.</td>', 'Very effective use of backlighting - good response to the challenge.', '2006-01-11 14:13:43.000000', NULL, 1),
(2026814, 279527, 30982, '<td valign="top">Seems a bit more "underlit" than "backlit" but a gorgeous shot just the same.</td>', 'Seems a bit more "underlit" than "backlit" but a gorgeous shot just the same.', '2006-01-11 14:14:31.000000', NULL, 1),
(2026824, 278544, 30982, '<td valign="top">Best of the fruity shots.</td>', 'Best of the fruity shots.', '2006-01-11 14:17:16.000000', NULL, 1),
(2026863, 277487, 47377, '<td valign="top">I would have cropped much tighter, so the lighter bit behind the head doesn''t show at least but probably also loose the ear  to totally focu attention on that gorgeous face.</td>', 'I would have cropped much tighter, so the lighter bit behind the head doesn''t show at least but probably also loose the ear  to totally focu attention on that gorgeous face.', '2006-01-11 14:31:34.000000', NULL, 1),
(2026871, 279272, 21915, '<td valign="top">Would have loved this to be a bit sharper</td>', 'Would have loved this to be a bit sharper', '2006-01-11 14:32:54.000000', NULL, 1),
(2026873, 277964, 46214, '<td valign="top">the whole disc should have been in in the picture and with an stronger backlight you could get interesting effects with the light shining trough</td>', 'the whole disc should have been in in the picture and with an stronger backlight you could get interesting effects with the light shining trough', '2006-01-11 14:33:25.000000', NULL, 1),
(2026880, 279469, 41397, '<td valign="top">Great Photo!!  Makes me want to go to the beach.</td>', 'Great Photo!!  Makes me want to go to the beach.', '2006-01-11 14:35:07.000000', NULL, 1),
(2026888, 278894, 47377, '<td valign="top">I think the orange at the bottom distracts and It would be better to not have it there...</td>', 'I think the orange at the bottom distracts and It would be better to not have it there...', '2006-01-11 14:37:46.000000', NULL, 1),
(2026898, 279411, 47377, '<td valign="top">I think this would have been very good with out the lale so the whole bottle neck wuld have been clear. I fing the dark blob quite distracitng.</td>', 'I think this would have been very good with out the lale so the whole bottle neck wuld have been clear. I fing the dark blob quite distracitng.', '2006-01-11 14:40:56.000000', NULL, 1),
(2026906, 279434, 47377, '<td valign="top">because not more water drops show up on the pepper, the water in the forground just looks messy... would have been nicer all dry to see a nice clear reflection.</td>', 'because not more water drops show up on the pepper, the water in the forground just looks messy... would have been nicer all dry to see a nice clear reflection.', '2006-01-11 14:42:53.000000', NULL, 1),
(2026920, 279368, 47377, '<td valign="top">although I like the distortion of the nife in the glass I''m finfig the the set up around the glasses with the table setting and the folds in the table cloth distracting. The glass are nice and clean and sharp but the surroundings let them down.</td>', 'although I like the distortion of the nife in the glass I''m finfig the the set up around the glasses with the table setting and the folds in the table cloth distracting. The glass are nice and clean and sharp but the surroundings let them down.', '2006-01-11 14:46:11.000000', NULL, 1),
(2026923, 278995, 33161, '<td valign="top">to small</td>', 'to small', '2006-01-11 14:46:41.000000', NULL, 1),
(2026942, 279593, 33535, '<td valign="top">perfect.like the atmosphere and also the ligthing.<br/>great take on the challenge.add it to my favs ;P</td>', 'perfect.like the atmosphere and also the ligthing.great take on the challenge.add it to my favs ;P', '2006-01-11 14:52:37.000000', NULL, 1),
(2026952, 277607, 47377, '<td valign="top">I like this... just wonder whether it would have been better without the brush and to just have the glass bar across the paint. I just love that effect.</td>', 'I like this... just wonder whether it would have been better without the brush and to just have the glass bar across the paint. I just love that effect.', '2006-01-11 14:54:46.000000', NULL, 1),
(2026954, 278138, 39349, '<td valign="top">Indeed it is..nice job with this sparking image.</td>', 'Indeed it is..nice job with this sparking image.', '2006-01-11 14:55:16.000000', NULL, 1),
(2026959, 279272, 39349, '<td valign="top">Seems a tad out of focus but I like the composition and the detail you''ve captured in the fringe of the pods.</td>', 'Seems a tad out of focus but I like the composition and the detail you''ve captured in the fringe of the pods.', '2006-01-11 14:56:12.000000', NULL, 1),
(2026975, 279374, 15711, '<td valign="top">This is interesting.  I don''t see it as much as backlit but light from one direction.  But having said that, it''s still a pretty image. I think it might be a bit more pleasing if you weren''t under her chin, but more to the side on an even plain. Since she has a rather prominent lower jaw area, the angle accentuates that. I like the lighting alhtough it''s a tad harsh above her right eye.</td>', 'This is interesting.  I don''t see it as much as backlit but light from one direction.  But having said that, it''s still a pretty image. I think it might be a bit more pleasing if you weren''t under her chin, but more to the side on an even plain. Since she has a rather prominent lower jaw area, the angle accentuates that. I like the lighting alhtough it''s a tad harsh above her right eye.', '2006-01-11 15:01:04.000000', NULL, 1),
(2026980, 279572, 15711, '<td valign="top">I truly love this, but the description specifically said no silhouettes. BUMMER - this is a lovely image.</td>', 'I truly love this, but the description specifically said no silhouettes. BUMMER - this is a lovely image.', '2006-01-11 15:02:34.000000', NULL, 1),
(2026981, 277971, 46371, '<td valign="top">I SEE YOUR CAMERA!!!! READ THE RULES.</td>', 'I SEE YOUR CAMERA!!!! READ THE RULES.', '2006-01-11 15:02:34.000000', NULL, 1),
(2026988, 279074, 50680, '<td valign="top">Very nice. So clean and simple.</td>', 'Very nice. So clean and simple.', '2006-01-11 15:04:58.000000', NULL, 1),
(2026989, 278989, 45524, '<td valign="top">This is a good approach and good idea for the challenge, however the photo is way too busy and I just cant find a focal point that draws my attention and keeps it.</td>', 'This is a good approach and good idea for the challenge, however the photo is way too busy and I just cant find a focal point that draws my attention and keeps it.', '2006-01-11 15:05:00.000000', NULL, 1),
(2026990, 278071, 50680, '<td valign="top">Nice job making something we walk by everyday and take for granted look so majestic and beautiful. Or you have some giant killer weeds where you live.<br/>Very nice one of my favorites.</td>', 'Nice job making something we walk by everyday and take for granted look so majestic and beautiful. Or you have some giant killer weeds where you live.Very nice one of my favorites.', '2006-01-11 15:05:11.000000', NULL, 1),
(2026999, 277186, 45524, '<td valign="top">This is a great entry into the challenge, nicely composed, but the focus is just off, it seems too fuzzy. Had the focus been spot on it would have been a 9.</td>', 'This is a great entry into the challenge, nicely composed, but the focus is just off, it seems too fuzzy. Had the focus been spot on it would have been a 9.', '2006-01-11 15:08:18.000000', NULL, 1),
(2027006, 276708, 47377, '<td valign="top">wow, I just love this. the colour, the waterdrops, DOF...  this is the kind o picture I want to take!  well done 10</td>', 'wow, I just love this. the colour, the waterdrops, DOF...  this is the kind o picture I want to take!  well done 10', '2006-01-11 15:11:19.000000', NULL, 1),
(2027010, 279552, 47377, '<td valign="top">so simple, yet so beautiful. well done 9</td>', 'so simple, yet so beautiful. well done 9', '2006-01-11 15:11:39.000000', NULL, 1),
(2027015, 278043, 44490, '<td valign="top">Nice red and white colors, pretty, but not really backlit.</td>', 'Nice red and white colors, pretty, but not really backlit.', '2006-01-11 15:12:35.000000', NULL, 1),
(2027016, 278544, 47377, '<td valign="top">in my opinion this the best out of the "sliced fruit" entries in this challenge.  I love the colour and the contrast. well done  8</td>', 'in my opinion this the best out of the "sliced fruit" entries in this challenge.  I love the colour and the contrast. well done  8', '2006-01-11 15:12:53.000000', NULL, 1),
(2027066, 278025, 3087, '<td valign="top">Looks like burnished gold - what a lovely effect. Nice tight viewpoint too.</td>', 'Looks like burnished gold - what a lovely effect. Nice tight viewpoint too.', '2006-01-11 15:31:42.000000', NULL, 1),
(2027067, 276551, 3087, '<td valign="top">Potentially a great picture but marred for me by the date stamp nad by the soft focus.</td>', 'Potentially a great picture but marred for me by the date stamp nad by the soft focus.', '2006-01-11 15:32:05.000000', NULL, 1),
(2027068, 278560, 3087, '<td valign="top">Beautiful lighting! This without the fence in the background (not that I''m suggesting you could have avoided it - just dreaming/ imagining out loud) would be a killer shot!</td>', 'Beautiful lighting! This without the fence in the background (not that I''m suggesting you could have avoided it - just dreaming/ imagining out loud) would be a killer shot!', '2006-01-11 15:32:50.000000', NULL, 1),
(2027074, 279021, 3087, '<td valign="top">A really unusual example of backlighting - I really like how the low light paints the edge of each little hill in sweeping curves across the frame. Lack of sharp focus on large foreground tree canopy does marr the image for me - a deeper depth of field would work well here, in my opinion.</td>', 'A really unusual example of backlighting - I really like how the low light paints the edge of each little hill in sweeping curves across the frame. Lack of sharp focus on large foreground tree canopy does marr the image for me - a deeper depth of field would work well here, in my opinion.', '2006-01-11 15:33:59.000000', NULL, 1),
(2027076, 278769, 3087, '<td valign="top">Lovely choice of subject and great composition with that blurred line of grass in the distance. Doesn''t seem sharp enough in the foreground to me...</td>', 'Lovely choice of subject and great composition with that blurred line of grass in the distance. Doesn''t seem sharp enough in the foreground to me...', '2006-01-11 15:35:03.000000', NULL, 1),
(2027078, 279116, 3087, '<td valign="top">I suspect you''ll get a lot of comments about this being side-lighting rather than backlighting but it''s just a matter of a few degrees variation in viewpoint and I tink it''s a strong image, really nicely done.</td>', 'I suspect you''ll get a lot of comments about this being side-lighting rather than backlighting but it''s just a matter of a few degrees variation in viewpoint and I tink it''s a strong image, really nicely done.', '2006-01-11 15:35:53.000000', NULL, 1),
(2027083, 278138, 3087, '<td valign="top">Ooh - sparkler as light source - that IS a bright (and fun) idea! Nice one!</td>', 'Ooh - sparkler as light source - that IS a bright (and fun) idea! Nice one!', '2006-01-11 15:36:36.000000', NULL, 1),
(2027088, 279543, 3087, '<td valign="top">Oooh I dooooo like this! Love the quirky composition - love that the boots almost have a life of their own but at the same time are really just a representation of their owner and the also the life they lived. I love the floorboard reflections and also that little glimpse into the rest of the home, yet not enough detail to detract from the boots.</td>', 'Oooh I dooooo like this! Love the quirky composition - love that the boots almost have a life of their own but at the same time are really just a representation of their owner and the also the life they lived. I love the floorboard reflections and also that little glimpse into the rest of the home, yet not enough detail to detract from the boots.', '2006-01-11 15:37:53.000000', NULL, 1),
(2027091, 279215, 3087, '<td valign="top">Wow! What an amazing creature and what a great choice for this challenge. It''s really hard to really get a handle on where the light source is - perhaps it''s a touch too soft to provide a clearly backlit effect - so there is no glowing effect on/ through all those magical bristles. Simplicity of composition is excellent.</td>', 'Wow! What an amazing creature and what a great choice for this challenge. It''s really hard to really get a handle on where the light source is - perhaps it''s a touch too soft to provide a clearly backlit effect - so there is no glowing effect on/ through all those magical bristles. Simplicity of composition is excellent.', '2006-01-11 15:39:15.000000', NULL, 1),
(2027095, 279594, 3087, '<td valign="top">Oh wow, isn''t this just beautiful?! Not only is the lighting perfect but soo too is the composition and square crop and the beautiful bokeh too! I do like this!</td>', 'Oh wow, isn''t this just beautiful?! Not only is the lighting perfect but soo too is the composition and square crop and the beautiful bokeh too! I do like this!', '2006-01-11 15:40:09.000000', NULL, 1),
(2027100, 279572, 3087, '<td valign="top">Lovely halo on the hair! But, for me, that isn''t enough on it''s own - wonder if a reflector throwing some light onto the face (with the model facing the photographer, of course) might be more interesting? This is more abstract and may appeal more to some but for me it simply doesn''t have quite enough as it is, even though I like the red-burnished gold of the hair.</td>', 'Lovely halo on the hair! But, for me, that isn''t enough on it''s own - wonder if a reflector throwing some light onto the face (with the model facing the photographer, of course) might be more interesting? This is more abstract and may appeal more to some but for me it simply doesn''t have quite enough as it is, even though I like the red-burnished gold of the hair.', '2006-01-11 15:42:39.000000', NULL, 1),
(2027102, 278453, 3087, '<td valign="top">Very cool. I like this a lot. So ethereal, so soft, so beautifully toned and so perfectly minimal in content yet with that little detail to pull one in. And the centred composition is perfect for the image - it''s kind of rather bhuddist somehow.</td>', 'Very cool. I like this a lot. So ethereal, so soft, so beautifully toned and so perfectly minimal in content yet with that little detail to pull one in. And the centred composition is perfect for the image - it''s kind of rather bhuddist somehow.', '2006-01-11 15:43:47.000000', NULL, 1),
(2027107, 279406, 3087, '<td valign="top">Nice capture - good composition, great lighting. In my opinion, would be stronger with deeper depth of field that allowed face, body and tail to be in focus.</td>', 'Nice capture - good composition, great lighting. In my opinion, would be stronger with deeper depth of field that allowed face, body and tail to be in focus.', '2006-01-11 15:44:38.000000', NULL, 1),
(2027128, 278174, 49067, '<td valign="top">great shot. I suppose it''s silhouettesd half and half!</td>', 'great shot. I suppose it''s silhouettesd half and half!', '2006-01-11 15:53:10.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2027153, 278897, 37879, '<td valign="top">Looks like a silhouette to me with the lack of detail in horses.  Challenge description says no silhouettes.  Awesome photo though.</td>', 'Looks like a silhouette to me with the lack of detail in horses.  Challenge description says no silhouettes.  Awesome photo though.', '2006-01-11 16:03:47.000000', NULL, 1),
(2027159, 279469, 49561, '<td valign="top">Wonderful use of textures and lighting. I like the "lava-look" of the liquid. Very plasmic looking. The shell has a variety of textures that makes it visually pleasing. Great job. My high pick for a high placement in this challenge.</td>', 'Wonderful use of textures and lighting. I like the "lava-look" of the liquid. Very plasmic looking. The shell has a variety of textures that makes it visually pleasing. Great job. My high pick for a high placement in this challenge.', '2006-01-11 16:04:58.000000', NULL, 1),
(2027185, 279417, 3102, '<td valign="top">Well, she certainly is easy on the eyes... this was the first image that came up when I started voting on this challenge.  Hopefully the rest will be this pleasing!  :)</td>', 'Well, she certainly is easy on the eyes... this was the first image that came up when I started voting on this challenge.  Hopefully the rest will be this pleasing!  :)', '2006-01-11 16:10:33.000000', NULL, 1),
(2027196, 276878, 30982, '<td valign="top">Wow - definitely backlit!  Not fond of the subject, but the technique is very good!</td>', 'Wow - definitely backlit!  Not fond of the subject, but the technique is very good!', '2006-01-11 16:12:31.000000', NULL, 1),
(2027199, 277253, 50695, '<td valign="top">I don''t like "studio shots" but this pepper is so alive! nice.</td>', 'I don''t like "studio shots" but this pepper is so alive! nice.', '2006-01-11 16:13:06.000000', NULL, 1),
(2027204, 277826, 31005, '<td valign="top">I think if this was just taken a little more to the left and more of the gargolye it would really improve the shot and you could tell its lit from the back.</td>', 'I think if this was just taken a little more to the left and more of the gargolye it would really improve the shot and you could tell its lit from the back.', '2006-01-11 16:14:27.000000', NULL, 1),
(2027205, 279017, 50695, '<td valign="top">much more dynamic than the other flower shots.</td>', 'much more dynamic than the other flower shots.', '2006-01-11 16:14:33.000000', NULL, 1),
(2027209, 279499, 31005, '<td valign="top">interesting and I lik how you captured the sparke of the water.</td>', 'interesting and I lik how you captured the sparke of the water.', '2006-01-11 16:15:32.000000', NULL, 1),
(2027216, 277564, 31005, '<td valign="top">I think the soft focus on the tip of the stem takes something from it.  Not sure if it could have been taken w/the whole image and not looked flat.  I do like it.</td>', 'I think the soft focus on the tip of the stem takes something from it.  Not sure if it could have been taken w/the whole image and not looked flat.  I do like it.', '2006-01-11 16:16:48.000000', NULL, 1),
(2027220, 279102, 50695, '<td valign="top">that church looks fake! I call it Surrealist. 8.</td>', 'that church looks fake! I call it Surrealist. 8.', '2006-01-11 16:18:05.000000', NULL, 1),
(2027226, 279537, 50695, '<td valign="top">I like the texture of the water.</td>', 'I like the texture of the water.', '2006-01-11 16:20:16.000000', NULL, 1),
(2027242, 279417, 3459, '<td valign="top">Great image, very professional! 10</td>', 'Great image, very professional! 10', '2006-01-11 16:26:19.000000', NULL, 1),
(2027249, 278822, 50695, '<td valign="top">high score for darkness, but would have been higher if you cropped it more.</td>', 'high score for darkness, but would have been higher if you cropped it more.', '2006-01-11 16:28:43.000000', NULL, 1),
(2027301, 279417, 22734, '<td valign="top">Downright sexy and mweting and exceeding the challenge. I would have experimented with different placements of subject in the frame and yet I realize that the center (as is) is probably the best because it reduces the exhibition of the backlight glare. In other words if you shit subject left then a mass of of the glare will be in the viewers face. A very good effort because adequate lighting depicts the form. 7 on my first pass.</td>', 'Downright sexy and mweting and exceeding the challenge. I would have experimented with different placements of subject in the frame and yet I realize that the center (as is) is probably the best because it reduces the exhibition of the backlight glare. In other words if you shit subject left then a mass of of the glare will be in the viewers face. A very good effort because adequate lighting depicts the form. 7 on my first pass.', '2006-01-11 16:52:07.000000', NULL, 1),
(2027313, 279569, 41241, '<td valign="top">This is sidelighting not backlighting.  Unfair!<br/> <br/>Good photo though</td>', 'This is sidelighting not backlighting.  Unfair! Good photo though', '2006-01-11 16:57:19.000000', NULL, 1),
(2027316, 279175, 41241, '<td valign="top">not backlit really, its all lighted up just with his back with a bit more light, rather unfair submit</td>', 'not backlit really, its all lighted up just with his back with a bit more light, rather unfair submit', '2006-01-11 16:59:27.000000', NULL, 1),
(2027318, 279527, 50147, '<td valign="top">One word...Brilliant!</td>', 'One word...Brilliant!', '2006-01-11 17:00:25.000000', NULL, 1),
(2027320, 279482, 41241, '<td valign="top">thats bottom lit, not back</td>', 'thats bottom lit, not back', '2006-01-11 17:01:47.000000', NULL, 1),
(2027321, 279478, 50147, '<td valign="top">A bit too dark for me</td>', 'A bit too dark for me', '2006-01-11 17:02:06.000000', NULL, 1),
(2027322, 277256, 41241, '<td valign="top">how is this backlit when the lightsource is on the front?</td>', 'how is this backlit when the lightsource is on the front?', '2006-01-11 17:02:08.000000', NULL, 1),
(2027323, 279513, 41241, '<td valign="top">not backlit</td>', 'not backlit', '2006-01-11 17:02:37.000000', NULL, 1),
(2027326, 278124, 17507, '<td valign="top">looks like you used a fill flash to keep from losing detail in the foreground/shadow areas. good idea. The light, though it is behind the subject, is coming pretty strongly from camera right - for this challenge, I think that having the backlighting more directly behind your subject would have been more appropriate.</td>', 'looks like you used a fill flash to keep from losing detail in the foreground/shadow areas. good idea. The light, though it is behind the subject, is coming pretty strongly from camera right - for this challenge, I think that having the backlighting more directly behind your subject would have been more appropriate.', '2006-01-11 17:02:56.000000', NULL, 1),
