INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2028497, 276536, 245, '<td valign="top">You are one of the few photographers on this site that, when doing a geometric image like this, seems to be able to make it true. I can''t <i>stand</i> when people try to do this sort of shot without it being square, balanced, and centered nicely. A for attention to detail!</td>', 'You are one of the few photographers on this site that, when doing a geometric image like this, seems to be able to make it true. I can''t stand when people try to do this sort of shot without it being square, balanced, and centered nicely. A for attention to detail!', '2006-01-11 23:08:00.000000', NULL, 1),
(2028503, 279510, 33515, '<td valign="top">The idea is good and I like the motion of the net but IMO your subject became to much of a silhouette. 5</td>', 'The idea is good and I like the motion of the net but IMO your subject became to much of a silhouette. 5', '2006-01-11 23:09:10.000000', NULL, 1),
(2028506, 276518, 33515, '<td valign="top">IMO your subject became to much of a silhouette.</td>', 'IMO your subject became to much of a silhouette.', '2006-01-11 23:09:46.000000', NULL, 1),
(2028510, 278735, 33515, '<td valign="top">Very nice, nothing is to burned out and the reflection is the water is a nice touch with the crop. 8</td>', 'Very nice, nothing is to burned out and the reflection is the water is a nice touch with the crop. 8', '2006-01-11 23:10:59.000000', NULL, 1),
(2028568, 278389, 29513, '<td valign="top">Nice shot.  Just a matter of personal preference but I think I would rather see the whole glass in sharper focus.</td>', 'Nice shot.  Just a matter of personal preference but I think I would rather see the whole glass in sharper focus.', '2006-01-11 23:31:48.000000', NULL, 1),
(2028578, 278071, 29513, '<td valign="top">I just love the framing, the lighting, the perspective. . .<br/>Wow!</td>', 'I just love the framing, the lighting, the perspective. . .Wow!', '2006-01-11 23:34:12.000000', NULL, 1),
(2028579, 279594, 2560, '<td valign="top">I love the snowflake shots. If it snowed here much I would shoot alot of this type stuff(well before I moved to a warmer area).  This looks pretty good to me but I think if you cropped it even it would still meet the rule of 3rds.  However this crop would be more marketable due to all the negative space on the right. I dont think I need to point out the sharpening artifacts along the bottom.  Not much you can due under the rules-sharpen or dont.  good luck and hope I vote on enough to not get thrown out ;)</td>', 'I love the snowflake shots. If it snowed here much I would shoot alot of this type stuff(well before I moved to a warmer area).  This looks pretty good to me but I think if you cropped it even it would still meet the rule of 3rds.  However this crop would be more marketable due to all the negative space on the right. I dont think I need to point out the sharpening artifacts along the bottom.  Not much you can due under the rules-sharpen or dont.  good luck and hope I vote on enough to not get thrown out ;)', '2006-01-11 23:34:16.000000', NULL, 1),
(2028594, 279552, 48298, '<td valign="top">Lovely simple composition.  10.</td>', 'Lovely simple composition.  10.', '2006-01-11 23:38:48.000000', NULL, 1),
(2028595, 278197, 47401, '<td valign="top">Wow, I really like this, gj.</td>', 'Wow, I really like this, gj.', '2006-01-11 23:39:05.000000', NULL, 1),
(2028599, 279469, 48298, '<td valign="top">Oooooh...stunning color, comp &amp; detail.  10.</td>', 'Oooooh...stunning color, comp & detail.  10.', '2006-01-11 23:40:59.000000', NULL, 1),
(2028601, 276653, 47401, '<td valign="top">In my opinion, I think it would look more serious if you had cropped out the city.</td>', 'In my opinion, I think it would look more serious if you had cropped out the city.', '2006-01-11 23:41:48.000000', NULL, 1),
(2028606, 279377, 48298, '<td valign="top">Fascinating to see the jet of water with the fire backlighting it!  I know that some people may tell you that this is a silhouette, but I don''t think it is, because of the reflective strips on their gear.  10.</td>', 'Fascinating to see the jet of water with the fire backlighting it!  I know that some people may tell you that this is a silhouette, but I don''t think it is, because of the reflective strips on their gear.  10.', '2006-01-11 23:42:42.000000', NULL, 1),
(2028608, 278025, 47401, '<td valign="top">Super cool!</td>', 'Super cool!', '2006-01-11 23:43:46.000000', NULL, 1),
(2028611, 279529, 2560, '<td valign="top">I like it.   good luck</td>', 'I like it.   good luck', '2006-01-11 23:44:19.000000', NULL, 1),
(2028621, 278125, 48298, '<td valign="top">Cool!  My original concept (which I didn''t go with) was of a clear video game controller...so I''m giving you a high score for your obviously imaginative thinking.  LOL  Background texture is nice, too.</td>', 'Cool!  My original concept (which I didn''t go with) was of a clear video game controller...so I''m giving you a high score for your obviously imaginative thinking.  LOL  Background texture is nice, too.', '2006-01-11 23:47:27.000000', NULL, 1),
(2028627, 278160, 48298, '<td valign="top">Nice focus on the scruffy beard!  Dreadlocks look cool backlit.</td>', 'Nice focus on the scruffy beard!  Dreadlocks look cool backlit.', '2006-01-11 23:49:14.000000', NULL, 1),
