(2029504, 279559, 46885, '<td valign="top">Great pic. But are we to believe that no advance editing was involved in that halo around the tree. Actually, even admitting this, the dodging could be less obvious. For these reasons - 6.</td>', 'Great pic. But are we to believe that no advance editing was involved in that halo around the tree. Actually, even admitting this, the dodging could be less obvious. For these reasons - 6.', '2006-01-12 09:12:04.000000', NULL, 1),
(2029506, 276572, 33161, '<td valign="top">nice picture.</td>', 'nice picture.', '2006-01-12 09:12:38.000000', NULL, 1),
(2029508, 276653, 46885, '<td valign="top">It''s a good idea of light and cross, but so blandly applied. A bit more play with angle and position of elements would make it much better.</td>', 'It''s a good idea of light and cross, but so blandly applied. A bit more play with angle and position of elements would make it much better.', '2006-01-12 09:13:18.000000', NULL, 1),
