(2033076, 279175, 42328, '<td valign="top">Incredible image.</td>', 'Incredible image.', '2006-01-13 12:56:01.000000', NULL, 1),
(2033085, 279534, 42328, '<td valign="top">One of my faves. So interesting to view.  Great job.</td>', 'One of my faves. So interesting to view.  Great job.', '2006-01-13 12:59:13.000000', NULL, 1),
(2033106, 278065, 42328, '<td valign="top">Wonderful! 9</td>', 'Wonderful! 9', '2006-01-13 13:06:23.000000', NULL, 1),
(2033129, 277268, 42328, '<td valign="top">I think this would score higher if the lamp was concealed and you cropped tighter in on a specific (highlighted) area of the plant so the viewer can see some details in the leaves. Also, in doing so it would eliminate the distraction of the corner of the wall.</td>', 'I think this would score higher if the lamp was concealed and you cropped tighter in on a specific (highlighted) area of the plant so the viewer can see some details in the leaves. Also, in doing so it would eliminate the distraction of the corner of the wall.', '2006-01-13 13:16:41.000000', NULL, 1),
