(2033256, 279469, 50322, '<td valign="top">very pretty, but doesnt look backlit</td>', 'very pretty, but doesnt look backlit', '2006-01-13 14:11:50.000000', NULL, 1),
(2033257, 279268, 42100, '<td valign="top">This underwater photograph was a great choice for the backlit challenge.  The aqua tones are very nice and relaxing.  But the business of the composition takes away from the relaxed feeling, and has my eyes jumping all over.  Emphasizing a key subject to the photo would really help.</td>', 'This underwater photograph was a great choice for the backlit challenge.  The aqua tones are very nice and relaxing.  But the business of the composition takes away from the relaxed feeling, and has my eyes jumping all over.  Emphasizing a key subject to the photo would really help.', '2006-01-13 14:12:43.000000', NULL, 1),
(2033260, 277145, 50322, '<td valign="top">really pretty, but i wish the tower was a little brighter</td>', 'really pretty, but i wish the tower was a little brighter', '2006-01-13 14:13:32.000000', NULL, 1),
