INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2033388, 279074, 33161, '<td valign="top">best picture yet! good luck</td>', 'best picture yet! good luck', '2006-01-13 14:44:28.000000', NULL, 1),
(2033391, 279527, 33161, '<td valign="top">this is great, I dont see how you guys do it.</td>', 'this is great, I dont see how you guys do it.', '2006-01-13 14:45:33.000000', NULL, 1),
(2033427, 276708, 42100, '<td valign="top">Outstanding photograph!  By far my favorite of this challenge.  The color and DOF are amazing.  I''m not sure if this is more of a macro or an abstract, either way excellent work.  <br/> <br/></td>', 'Outstanding photograph!  By far my favorite of this challenge.  The color and DOF are amazing.  I''m not sure if this is more of a macro or an abstract, either way excellent work.   ', '2006-01-13 14:55:36.000000', NULL, 1),
(2033454, 277971, 24363, '<td valign="top">ummm. not sure what to say....  1)focus 2)have someone else take it for you</td>', 'ummm. not sure what to say....  1)focus 2)have someone else take it for you', '2006-01-13 15:05:38.000000', NULL, 1),
(2033455, 279537, 49865, '<td valign="top">This is an incredible photo. Sure the oil platform is silhouetted... but, I feel like the waves are the subject anyway, and those are what really draw me into this photo.</td>', 'This is an incredible photo. Sure the oil platform is silhouetted... but, I feel like the waves are the subject anyway, and those are what really draw me into this photo.', '2006-01-13 15:05:39.000000', NULL, 1),
(2033458, 278995, 24363, '<td valign="top">to small..</td>', 'to small..', '2006-01-13 15:06:35.000000', NULL, 1),
(2033469, 279350, 24363, '<td valign="top">snapshot... no focus</td>', 'snapshot... no focus', '2006-01-13 15:09:28.000000', NULL, 1),
(2033475, 278905, 22046, '<td valign="top">I admit I''ve seen this before... but never mind. This is still my favorite picture in this challenge. The lighting is exquisite and the picture is emotionally evocative. Beautiful!</td>', 'I admit I''ve seen this before... but never mind. This is still my favorite picture in this challenge. The lighting is exquisite and the picture is emotionally evocative. Beautiful!', '2006-01-13 15:14:06.000000', NULL, 1),
(2033479, 279448, 22046, '<td valign="top">Great choice of a background for this. Very striking image.</td>', 'Great choice of a background for this. Very striking image.', '2006-01-13 15:15:14.000000', NULL, 1),
(2033480, 276708, 22046, '<td valign="top">Pretty flower. Good use of depth of field and bocah.</td>', 'Pretty flower. Good use of depth of field and bocah.', '2006-01-13 15:15:49.000000', NULL, 1),
(2033482, 278165, 22046, '<td valign="top">This is extremely cool and one of my choices for a 10 rating. Love the sharp focus, the great color and the intersting design. I''m wondering what the source of the red color is?</td>', 'This is extremely cool and one of my choices for a 10 rating. Love the sharp focus, the great color and the intersting design. I''m wondering what the source of the red color is?', '2006-01-13 15:16:36.000000', NULL, 1),
(2033486, 279552, 22046, '<td valign="top">I''m assuming that the lighter areas come from a light behind the leaf. It''s not totally clear that is the case but I''m going to assume it is. Therefore I find this on topic and can rate on the merit of the photo which is very high. The composition is good. The color is good. The element of design is great. I really like this.</td>', 'I''m assuming that the lighter areas come from a light behind the leaf. It''s not totally clear that is the case but I''m going to assume it is. Therefore I find this on topic and can rate on the merit of the photo which is very high. The composition is good. The color is good. The element of design is great. I really like this.', '2006-01-13 15:18:18.000000', NULL, 1),
(2033487, 277607, 22046, '<td valign="top">Fun idea well executed. I see more than Roy and G and Biv in here. ;-)</td>', 'Fun idea well executed. I see more than Roy and G and Biv in here. ;-)', '2006-01-13 15:18:53.000000', NULL, 1),
(2033493, 276572, 22046, '<td valign="top">This is the best backlit bird. He''s in sharp focus and the composition is interesting.</td>', 'This is the best backlit bird. He''s in sharp focus and the composition is interesting.', '2006-01-13 15:20:47.000000', NULL, 1),
(2033496, 279138, 22046, '<td valign="top">Great lighting here. I also love the ice blue color in the background.</td>', 'Great lighting here. I also love the ice blue color in the background.', '2006-01-13 15:21:13.000000', NULL, 1),
(2033500, 279502, 22046, '<td valign="top">What a touching photograph. Don''t know how you happened to be here but you captured a strong emotional moment.</td>', 'What a touching photograph. Don''t know how you happened to be here but you captured a strong emotional moment.', '2006-01-13 15:21:47.000000', NULL, 1),
(2033503, 278623, 22046, '<td valign="top">The color here is wonderful. My only complaint is that the slices seem to be a bit out of focus.</td>', 'The color here is wonderful. My only complaint is that the slices seem to be a bit out of focus.', '2006-01-13 15:22:18.000000', NULL, 1),
(2033504, 278909, 22046, '<td valign="top">Good sharp focus. Interesting limited palette. I like this.</td>', 'Good sharp focus. Interesting limited palette. I like this.', '2006-01-13 15:22:42.000000', NULL, 1),
(2033506, 279239, 22046, '<td valign="top">The colors here are quite wonderful.</td>', 'The colors here are quite wonderful.', '2006-01-13 15:22:58.000000', NULL, 1),
(2033513, 278233, 29148, '<td valign="top">I light the water highlight in back of the little tree. Very novel shot.</td>', 'I light the water highlight in back of the little tree. Very novel shot.', '2006-01-13 15:24:23.000000', NULL, 1),
(2033519, 279594, 29148, '<td valign="top">Lovely shot all the way around.</td>', 'Lovely shot all the way around.', '2006-01-13 15:26:01.000000', NULL, 1),
(2033520, 279102, 22046, '<td valign="top">Simple with an interesting color scheme.</td>', 'Simple with an interesting color scheme.', '2006-01-13 15:26:05.000000', NULL, 1),
(2033521, 278132, 22046, '<td valign="top">Lovely simple composition. I like the streaks of color in the vase. Perfect for the challenge theme.</td>', 'Lovely simple composition. I like the streaks of color in the vase. Perfect for the challenge theme.', '2006-01-13 15:26:39.000000', NULL, 1),
(2033522, 277963, 22046, '<td valign="top">Beautiful lighting.</td>', 'Beautiful lighting.', '2006-01-13 15:26:52.000000', NULL, 1),
(2033524, 278621, 22046, '<td valign="top">What I like most about this is the shadow on the petal.</td>', 'What I like most about this is the shadow on the petal.', '2006-01-13 15:27:26.000000', NULL, 1),
(2033527, 279081, 22046, '<td valign="top">Very moody photograph. The surfer makes the picture. Also the lines of water coming up the beach are great. They lead the eye out to sea.</td>', 'Very moody photograph. The surfer makes the picture. Also the lines of water coming up the beach are great. They lead the eye out to sea.', '2006-01-13 15:28:07.000000', NULL, 1),
(2033528, 278772, 29148, '<td valign="top">Very intesting shot the the Alabama. Great job with the lighting.</td>', 'Very intesting shot the the Alabama. Great job with the lighting.', '2006-01-13 15:28:24.000000', NULL, 1),
(2033537, 278105, 22046, '<td valign="top">This is very cool. I like how you turned the bottles into figures.</td>', 'This is very cool. I like how you turned the bottles into figures.', '2006-01-13 15:29:59.000000', NULL, 1),
(2033539, 277026, 22046, '<td valign="top">Very cool. Your focus is perfect. The ball is sharp and the reflection isn''t. Works very well. This is one of my top picks.</td>', 'Very cool. Your focus is perfect. The ball is sharp and the reflection isn''t. Works very well. This is one of my top picks.', '2006-01-13 15:31:06.000000', NULL, 1),
