INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2044054, 278066, 38706, '<td valign="top">I like this as an almost abstract - nice colours and has that feeling that the dice are about to fall which is great.</td>', 'I like this as an almost abstract - nice colours and has that feeling that the dice are about to fall which is great.', '2006-01-16 16:50:03.000000', NULL, 1),
(2044071, 277454, 48292, '<td valign="top">I would have taken out the power lines with the healing brush but I think this would have been a good photo without that</td>', 'I would have taken out the power lines with the healing brush but I think this would have been a good photo without that', '2006-01-16 16:53:08.000000', NULL, 1),
(2044251, 278835, 7628, '<td valign="top">I like how the colors of the fish match the colors of the writing.  The backlighting doesn''t really help the image - it decreases the detail on the fish.  The focus is not sharp and the bumped up saturation and contrast looses more details and has created some odd artifacts in the white background.</td>', 'I like how the colors of the fish match the colors of the writing.  The backlighting doesn''t really help the image - it decreases the detail on the fish.  The focus is not sharp and the bumped up saturation and contrast looses more details and has created some odd artifacts in the white background.', '2006-01-16 17:27:26.000000', NULL, 1),
(2044294, 277454, 7628, '<td valign="top">Lovely colors in this scene.  The backlighting makes the mountains blue, but has rendered the tree and the light pole silhouettes - which the challenge details warn against - the backlighting was meant to add to the effect of the image not be the whole effect.  Even with a silhouette as the desired effect, these subjects aren''t very interesting, neither is the composition dramatic or meaningful.  Perhaps if the tree filled the frame, or if the wires were composed in better relation to the rest of the image.</td>', 'Lovely colors in this scene.  The backlighting makes the mountains blue, but has rendered the tree and the light pole silhouettes - which the challenge details warn against - the backlighting was meant to add to the effect of the image not be the whole effect.  Even with a silhouette as the desired effect, these subjects aren''t very interesting, neither is the composition dramatic or meaningful.  Perhaps if the tree filled the frame, or if the wires were composed in better relation to the rest of the image.', '2006-01-16 17:33:44.000000', NULL, 1),
(2044306, 278623, 31586, '<td valign="top">lovely to view on this dreary winter day, Karen</td>', 'lovely to view on this dreary winter day, Karen', '2006-01-16 17:36:02.000000', NULL, 1),
(2044310, 278250, 7628, '<td valign="top">I like the waay the water catches the light and makes you backlighting a subject not just lighting.  I like how the composition balances the figure in the foreground and the figure behind the water.  Wish her feet weren''t cropped, and his head (?).  The building in the background is a bit distracting.  Wish there were more details in the foreground figure, she is also a bit out of focus.</td>', 'I like the waay the water catches the light and makes you backlighting a subject not just lighting.  I like how the composition balances the figure in the foreground and the figure behind the water.  Wish her feet weren''t cropped, and his head (?).  The building in the background is a bit distracting.  Wish there were more details in the foreground figure, she is also a bit out of focus.', '2006-01-16 17:36:27.000000', NULL, 1),
(2044312, 279215, 31586, '<td valign="top">Thats a cutie</td>', 'Thats a cutie', '2006-01-16 17:36:36.000000', NULL, 1),
(2044329, 279592, 7628, '<td valign="top">The light coming through the center is so bright in relation to the orange it draws your eye away  - and the imperfect shape of the hole detracts from the symetry  and doesn''t add to the composition.  Focus is not sharp.</td>', 'The light coming through the center is so bright in relation to the orange it draws your eye away  - and the imperfect shape of the hole detracts from the symetry  and doesn''t add to the composition.  Focus is not sharp.', '2006-01-16 17:38:51.000000', NULL, 1),
(2044350, 279535, 31586, '<td valign="top">Hey, I know how you did this! I backlit paper once and recieved alot of critiques saying "It would look so much better white" I like the off white and texture to the background.  Good Luck  Karen</td>', 'Hey, I know how you did this! I backlit paper once and recieved alot of critiques saying "It would look so much better white" I like the off white and texture to the background.  Good Luck  Karen', '2006-01-16 17:41:52.000000', NULL, 1),
(2044354, 279526, 7628, '<td valign="top">Very nice lighting - the reflection off the counter top really highlights the humerous(frog) part of your subject - nice even lighting on the normal(coffee cup) part of the subject.  This is exactly what the chalenge calls for! Perhaps could be a little brighter and a bit more contrast a bit more color saturation?</td>', 'Very nice lighting - the reflection off the counter top really highlights the humerous(frog) part of your subject - nice even lighting on the normal(coffee cup) part of the subject.  This is exactly what the chalenge calls for! Perhaps could be a little brighter and a bit more contrast a bit more color saturation?', '2006-01-16 17:42:20.000000', NULL, 1),
(2044363, 279578, 7628, '<td valign="top">DOF and backlight do a nice job of highlighting the subject.  Not a very interesting composition, or context - perhaps you could have made more of the backlit leaves and grass in the foreground as a compositional part of the image?</td>', 'DOF and backlight do a nice job of highlighting the subject.  Not a very interesting composition, or context - perhaps you could have made more of the backlit leaves and grass in the foreground as a compositional part of the image?', '2006-01-16 17:44:10.000000', NULL, 1),
(2044383, 279215, 7628, '<td valign="top">Lovely subject and nice composition - seems very dark, and a bit too yellow.</td>', 'Lovely subject and nice composition - seems very dark, and a bit too yellow.', '2006-01-16 17:47:36.000000', NULL, 1),
(2044427, 277487, 31586, '<td valign="top">So Sweet, My Favorite  Karen    a 10</td>', 'So Sweet, My Favorite  Karen    a 10', '2006-01-16 17:54:50.000000', NULL, 1),
