(2047814, 278125, 43340, '<td valign="top">Very clean shot.</td>', 'Very clean shot.', '2006-01-17 11:25:08.000000', NULL, 1),
(2047816, 278727, 11738, '<td valign="top">I think this could have used some more contrast to enhance the rays even more.</td>', 'I think this could have used some more contrast to enhance the rays even more.', '2006-01-17 11:25:37.000000', NULL, 1),
