(2048681, 279502, 13879, '<td valign="top">Powerful. I really hope all went well.</td>', 'Powerful. I really hope all went well.', '2006-01-17 14:13:38.000000', NULL, 1),
(2048698, 279506, 29442, '<td valign="top">Great composure, the focus seems just a tad off unless you''re using a soft focus filter or lens. I think some of the soft, dreamy effect would have been there with the wide aperture alone and been better with one sharp area of focus (the yellow flower for instance).</td>', 'Great composure, the focus seems just a tad off unless you''re using a soft focus filter or lens. I think some of the soft, dreamy effect would have been there with the wide aperture alone and been better with one sharp area of focus (the yellow flower for instance).', '2006-01-17 14:17:27.000000', NULL, 1),
