(2048797, 276910, 29442, '<td valign="top">Nice light balance between foreground and background.</td>', 'Nice light balance between foreground and background.', '2006-01-17 14:40:30.000000', NULL, 1),
(2048955, 279276, 10124, '<td valign="top">Wow! Excellent. I give it a 10.</td>', 'Wow! Excellent. I give it a 10.', '2006-01-17 15:24:33.000000', NULL, 1),
