(2049374, 278478, 32854, '<td valign="top">interesting.. but the blown-out highlights are distracting i believe</td>', 'interesting.. but the blown-out highlights are distracting i believe', '2006-01-17 17:05:52.000000', NULL, 1),
(2049379, 278702, 32854, '<td valign="top">I like the detail, but the light seems a tad too harsh. [7]</td>', 'I like the detail, but the light seems a tad too harsh. [7]', '2006-01-17 17:07:12.000000', NULL, 1),
(2049391, 278906, 32854, '<td valign="top">I like this shot. Nice composition. The leaf is a little underexposed though.</td>', 'I like this shot. Nice composition. The leaf is a little underexposed though.', '2006-01-17 17:09:57.000000', NULL, 1),
(2049404, 278061, 32854, '<td valign="top">Nice DOF. This photograph is open to interpretation, a wonderful quality common to many great photographs.</td>', 'Nice DOF. This photograph is open to interpretation, a wonderful quality common to many great photographs.', '2006-01-17 17:13:28.000000', NULL, 1),
(2049411, 279175, 32854, '<td valign="top">This is quite the interesting photograph, and the smoke looks pretty cool. The only thing that bothers me is the man in the background; he clashes with the smoke.</td>', 'This is quite the interesting photograph, and the smoke looks pretty cool. The only thing that bothers me is the man in the background; he clashes with the smoke.', '2006-01-17 17:16:10.000000', NULL, 1),
(2049419, 279449, 32854, '<td valign="top">This photograph is beautiful. I love the reflection, white trees, and smoky sky. Everything seems to blend so nicely, however, I would have honestly prefered a straight horizon. [8]</td>', 'This photograph is beautiful. I love the reflection, white trees, and smoky sky. Everything seems to blend so nicely, however, I would have honestly prefered a straight horizon. [8]', '2006-01-17 17:18:46.000000', NULL, 1),
(2049421, 276551, 39465, '<td valign="top">I really love this shot, but the time stamp just stands out as an eyesore :( if not for that this picture is easily a 9 or a 10.</td>', 'I really love this shot, but the time stamp just stands out as an eyesore :( if not for that this picture is easily a 9 or a 10.', '2006-01-17 17:19:12.000000', NULL, 1),
(2049431, 279045, 32854, '<td valign="top">Interesting. Vignetting brings greater attention to subject. Nice compostion, too. [7]</td>', 'Interesting. Vignetting brings greater attention to subject. Nice compostion, too. [7]', '2006-01-17 17:20:29.000000', NULL, 1),
(2049433, 279082, 39465, '<td valign="top">Your subject is in sillhouetee</td>', 'Your subject is in sillhouetee', '2006-01-17 17:21:14.000000', NULL, 1),
(2049436, 277898, 39465, '<td valign="top">Wow. I love this photo. I really get a lot of sensations from this. autumn turning to winter? Or perhaps winter slowly becoming spring?  I think that it shows a lot of delicate work and care, and is captured at a perfect moment of light. Wonderful!</td>', 'Wow. I love this photo. I really get a lot of sensations from this. autumn turning to winter? Or perhaps winter slowly becoming spring?  I think that it shows a lot of delicate work and care, and is captured at a perfect moment of light. Wonderful!', '2006-01-17 17:21:45.000000', NULL, 1),
(2049440, 277474, 39465, '<td valign="top">Simply gorgeous shot. I love the location of the lighting and how this captures the ''essence'' of the drink as it comes into the glass.</td>', 'Simply gorgeous shot. I love the location of the lighting and how this captures the ''essence'' of the drink as it comes into the glass.', '2006-01-17 17:22:14.000000', NULL, 1),
(2049441, 279368, 32854, '<td valign="top">Good focus, although the cut-off glass is bothersome. I guess it goes down to personal preference.</td>', 'Good focus, although the cut-off glass is bothersome. I guess it goes down to personal preference.', '2006-01-17 17:22:17.000000', NULL, 1),
(2049443, 279116, 39465, '<td valign="top">Oh wow, I love this shot. Sensitive, dramatic, and a very inventive use of the theme.  You must give some details on how you accomplished this.</td>', 'Oh wow, I love this shot. Sensitive, dramatic, and a very inventive use of the theme.  You must give some details on how you accomplished this.', '2006-01-17 17:22:45.000000', NULL, 1),
(2049444, 278043, 39465, '<td valign="top">I love shots like this. Simplistic natural beauty. Good job!</td>', 'I love shots like this. Simplistic natural beauty. Good job!', '2006-01-17 17:23:00.000000', NULL, 1),
(2049445, 279499, 39465, '<td valign="top">Very nice, like the concept behind this shot. The execution is excellent.</td>', 'Very nice, like the concept behind this shot. The execution is excellent.', '2006-01-17 17:23:14.000000', NULL, 1),
(2049449, 277829, 32854, '<td valign="top">Hmm, this is pretty grainy, but I think it gives it character. What bothers me, however, is the whiteish cast.</td>', 'Hmm, this is pretty grainy, but I think it gives it character. What bothers me, however, is the whiteish cast.', '2006-01-17 17:24:16.000000', NULL, 1),
(2049455, 278197, 39465, '<td valign="top">A very crisp and well done shot.  I like how he looks normal (in that he''s not a poreless photoshop creature) while still having an air of sexy readiness to him.  The light angles capture the angles of his fact perfectly. While it seems at first like a normal model shot, his ''flaws'' draw you into the humanity.  It''s not an advert, it''s a piece out of a story!</td>', 'A very crisp and well done shot.  I like how he looks normal (in that he''s not a poreless photoshop creature) while still having an air of sexy readiness to him.  The light angles capture the angles of his fact perfectly. While it seems at first like a normal model shot, his ''flaws'' draw you into the humanity.  It''s not an advert, it''s a piece out of a story!', '2006-01-17 17:25:10.000000', NULL, 1),
(2049456, 279477, 39465, '<td valign="top">I can almost hear the song. Very good shot! Love the use of light and color in this one!</td>', 'I can almost hear the song. Very good shot! Love the use of light and color in this one!', '2006-01-17 17:25:27.000000', NULL, 1),
(2049457, 278287, 32854, '<td valign="top">Very awesome! but you''re cropping a part of him!</td>', 'Very awesome! but you''re cropping a part of him!', '2006-01-17 17:25:31.000000', NULL, 1),
(2049459, 279521, 39465, '<td valign="top">Nice moment. Great capture. The light works perfectly, and your title ties it together.</td>', 'Nice moment. Great capture. The light works perfectly, and your title ties it together.', '2006-01-17 17:25:42.000000', NULL, 1),
(2049461, 279594, 39465, '<td valign="top">Wow, exteremly delicate shot. Very impressed.</td>', 'Wow, exteremly delicate shot. Very impressed.', '2006-01-17 17:25:51.000000', NULL, 1),
(2049465, 278735, 39465, '<td valign="top">I love this because it captures that fine cusp between backlighting and a sillhouette.  Very delicate shot.</td>', 'I love this because it captures that fine cusp between backlighting and a sillhouette.  Very delicate shot.', '2006-01-17 17:26:06.000000', NULL, 1);
